CREATE TABLE "word_results" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "session_id" bigint NOT NULL,
  "word" varchar,
  "accuracy_score" numeric(5,2),
  "error_type" varchar,
  "created_at" timestamp DEFAULT (now())
);

CREATE INDEX ON "word_results" ("session_id");
CREATE INDEX ON "word_results" ("word");

ALTER TABLE "word_results"
  ADD FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") DEFERRABLE INITIALLY IMMEDIATE;
